import{_ as e,o,c as d,ai as a}from"./chunks/framework.CAnUr3M0.js";const S=JSON.parse('{"title":"网络协议与缓存","description":"","frontmatter":{},"headers":[],"relativePath":"browser/network.md","filePath":"browser/network.md"}'),r={name:"browser/network.md"};function i(l,t,s,n,h,c){return o(),d("div",null,[...t[0]||(t[0]=[a(`<h1 id="网络协议与缓存" tabindex="-1">网络协议与缓存 <a class="header-anchor" href="#网络协议与缓存" aria-label="Permalink to &quot;网络协议与缓存&quot;">​</a></h1><blockquote><p>HTTP 缓存 · TCP 握手挥手 · HTTP/2/3 · HTTPS · Cookie/Session/Token/JWT/SSO · CDN · DNS</p></blockquote><hr><h2 id="一、http-缓存" tabindex="-1">一、HTTP 缓存 <a class="header-anchor" href="#一、http-缓存" aria-label="Permalink to &quot;一、HTTP 缓存&quot;">​</a></h2><h3 id="_1-强缓存" tabindex="-1">1. 强缓存 <a class="header-anchor" href="#_1-强缓存" aria-label="Permalink to &quot;1. 强缓存&quot;">​</a></h3><ul><li><code>Expires</code>（HTTP 1.0）：绝对时间，受本地时间影响</li><li><code>Cache-Control</code>（HTTP 1.1）：<code>max-age</code> 相对时间，优先级高于 Expires</li><li><code>no-cache</code>：需协商缓存；<code>no-store</code>：禁止缓存</li></ul><h3 id="_2-协商缓存" tabindex="-1">2. 协商缓存 <a class="header-anchor" href="#_2-协商缓存" aria-label="Permalink to &quot;2. 协商缓存&quot;">​</a></h3><ul><li><code>Last-Modified</code> / <code>If-Modified-Since</code>：基于最后修改时间（精确到秒）</li><li><code>ETag</code> / <code>If-None-Match</code>：基于文件内容编码，更精确，优先于 Last-Modified</li><li>命中返回 304，使用本地缓存</li></ul><hr><h2 id="二、tcp-http-协议" tabindex="-1">二、TCP / HTTP 协议 <a class="header-anchor" href="#二、tcp-http-协议" aria-label="Permalink to &quot;二、TCP / HTTP 协议&quot;">​</a></h2><h3 id="_1-tcp-三次握手与四次挥手" tabindex="-1">1. TCP 三次握手与四次挥手 <a class="header-anchor" href="#_1-tcp-三次握手与四次挥手" aria-label="Permalink to &quot;1. TCP 三次握手与四次挥手&quot;">​</a></h3><p><strong>三次握手</strong>：</p><ol><li>客户端 → SYN=1, seq=x → 服务端（SYN-SENT）</li><li>服务端 → SYN=1, ACK=1, seq=y, ack=x+1 → 客户端（SYN-RCVD）</li><li>客户端 → ACK=1, seq=x+1, ack=y+1 → 服务端（ESTABLISHED）</li></ol><p><strong>为什么三次</strong>：防止已失效的连接请求到达服务端导致错误建立连接</p><p><strong>四次挥手</strong>：</p><ol><li>主动方 → FIN=1 → 被动方（FIN-WAIT-1）</li><li>被动方 → ACK=1 → 主动方（CLOSE-WAIT，此时单向关闭）</li><li>被动方 → FIN=1 → 主动方（LAST-ACK）</li><li>主动方 → ACK=1 → 被动方（TIME-WAIT，等 2MSL 后 CLOSED）</li></ol><p><strong>为什么 TIME-WAIT</strong>：确保对方收到确认应答，若应答丢失对方会重发</p><h3 id="_2-五层因特网协议栈" tabindex="-1">2. 五层因特网协议栈 <a class="header-anchor" href="#_2-五层因特网协议栈" aria-label="Permalink to &quot;2. 五层因特网协议栈&quot;">​</a></h3><ol><li><strong>应用层</strong>（DNS、HTTP）：DNS 解析域名，发送 HTTP 请求</li><li><strong>传输层</strong>（TCP、UDP）：三次握手建立 TCP 连接</li><li><strong>网络层</strong>（IP、ARP）：IP 寻址，路由选择</li><li><strong>数据链路层</strong>（PPP）：封装成帧，添加 MAC 地址</li><li><strong>物理层</strong>：通过双绞线/光纤/电磁波传输比特流</li></ol><h3 id="_3-http-与-https-区别" tabindex="-1">3. HTTP 与 HTTPS 区别 <a class="header-anchor" href="#_3-http-与-https-区别" aria-label="Permalink to &quot;3. HTTP 与 HTTPS 区别&quot;">​</a></h3><ul><li>HTTPS = HTTP + SSL/TLS 加密，更安全</li><li>默认端口：HTTP 80，HTTPS 443</li><li>HTTPS 需要 SSL 证书，性能不如 HTTP（加解密+握手开销）</li></ul><h3 id="_4-http-2-特性" tabindex="-1">4. HTTP/2 特性 <a class="header-anchor" href="#_4-http-2-特性" aria-label="Permalink to &quot;4. HTTP/2 特性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>多路复用</td><td>单 TCP 连接并行加载多资源，无并发数限制</td></tr><tr><td>Server Push</td><td>服务器主动推送客户端可能需要的资源</td></tr><tr><td>头部压缩（HPACK）</td><td>维护头部表，后续请求只发差异字段</td></tr><tr><td>二进制帧传输</td><td>HTTP 报文拆分为头部帧和数据帧，解析更高效</td></tr><tr><td>持久连接</td><td>连接永久，不依赖 keep-alive 超时</td></tr></tbody></table><p><strong>升级要求</strong>：Nginx ≥ 1.10.0，OpenSSL ≥ 1.0.2，基本只支持 HTTPS</p><p><strong>HTTP/2 缺点</strong>：</p><ol><li>TCP 队头阻塞未彻底解决（丢包阻塞所有流）</li><li>丢包重传影响比 HTTP/1.1 更大</li><li>服务器瞬时压力暴增（无并发限制）</li></ol><h3 id="_5-https-握手过程-tls-1-2" tabindex="-1">5. HTTPS 握手过程（TLS 1.2） <a class="header-anchor" href="#_5-https-握手过程-tls-1-2" aria-label="Permalink to &quot;5. HTTPS 握手过程（TLS 1.2）&quot;">​</a></h3><ol><li><strong>Client-hello</strong>：客户端发送加密套件列表、随机数 random1</li><li><strong>Server-hello</strong>：服务端选定套件、返回证书 + 随机数 random2</li><li><strong>验证证书</strong>：从根证书开始逐级验证证书链（CA 签名）</li><li><strong>密钥交换</strong>：客户端生成 pre-master，用公钥加密发送；双方计算出对称会话密钥</li><li><strong>Finished</strong>：互发 Finished 验证握手成功，后续对称加密传输</li></ol><p><strong>对称加密 vs 非对称加密</strong>：握手用非对称加密协商密钥，传输用对称加密（兼顾安全与性能）</p><h3 id="_6-http-3-基于-quic" tabindex="-1">6. HTTP/3（基于 QUIC） <a class="header-anchor" href="#_6-http-3-基于-quic" aria-label="Permalink to &quot;6. HTTP/3（基于 QUIC）&quot;">​</a></h3><p><strong>核心改进</strong>：基于 UDP 的 QUIC 协议，彻底解决 TCP 队头阻塞</p><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>无队头阻塞</td><td>每个流独立传输，丢包只影响单个流</td></tr><tr><td>连接迁移</td><td>基于连接 ID，网络切换无需重建连接</td></tr><tr><td>快速握手</td><td>0-RTT/1-RTT 建立连接（HTTP/2 需 3-RTT）</td></tr><tr><td>内置加密</td><td>头部和载荷均加密</td></tr></tbody></table><p><strong>HTTP 协议演进</strong>：</p><table tabindex="0"><thead><tr><th>版本</th><th>传输层</th><th>核心特性</th><th>主要问题</th></tr></thead><tbody><tr><td>HTTP/1.1</td><td>TCP</td><td>文本协议、持久连接</td><td>队头阻塞、头部冗余</td></tr><tr><td>HTTP/2</td><td>TCP</td><td>多路复用、二进制帧</td><td>TCP 队头阻塞</td></tr><tr><td>HTTP/3</td><td>UDP(QUIC)</td><td>独立流、连接迁移、0-RTT</td><td>生态尚在完善</td></tr></tbody></table><h3 id="_7-post-请求-content-type" tabindex="-1">7. POST 请求 Content-Type <a class="header-anchor" href="#_7-post-请求-content-type" aria-label="Permalink to &quot;7. POST 请求 Content-Type&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Content-Type</th><th>用途</th><th>特点</th></tr></thead><tbody><tr><td><code>application/x-www-form-urlencoded</code></td><td>最常见表单</td><td>数据编码为 <code>key1=val1&amp;key2=val2</code></td></tr><tr><td><code>multipart/form-data</code></td><td>文件上传</td><td>boundary 分隔各字段，可传文件+键值对</td></tr><tr><td><code>application/json</code></td><td>JSON 格式</td><td>序列化 JSON 字符串</td></tr><tr><td><code>application/octet-stream</code></td><td>二进制流</td><td>只传二进制数据</td></tr></tbody></table><hr><h2 id="三、cookie-session-token-jwt-sso" tabindex="-1">三、Cookie / Session / Token / JWT / SSO <a class="header-anchor" href="#三、cookie-session-token-jwt-sso" aria-label="Permalink to &quot;三、Cookie / Session / Token / JWT / SSO&quot;">​</a></h2><h3 id="_1-cookie" tabindex="-1">1. Cookie <a class="header-anchor" href="#_1-cookie" aria-label="Permalink to &quot;1. Cookie&quot;">​</a></h3><ul><li>HTTP 是<strong>无状态协议</strong>，Cookie 用于维护会话状态</li><li>存储在<strong>客户端</strong>，下次请求同一服务器时自动携带</li><li>Cookie <strong>不可跨域</strong>（同一级/二级域名间可通过 domain 共享）</li></ul><table tabindex="0"><thead><tr><th>属性</th><th>说明</th></tr></thead><tbody><tr><td><code>domain</code></td><td>所属域名，默认当前域名</td></tr><tr><td><code>path</code></td><td>生效路径，默认 <code>/</code></td></tr><tr><td><code>maxAge</code></td><td>失效时间（秒），负数=临时，0=删除</td></tr><tr><td><code>secure</code></td><td>仅 HTTPS 传输</td></tr><tr><td><code>httpOnly</code></td><td>JS 无法读取（防 XSS）</td></tr></tbody></table><ul><li>单个 Cookie ≤ 4KB，一个网站最多约 20 个</li></ul><h3 id="_2-session" tabindex="-1">2. Session <a class="header-anchor" href="#_2-session" aria-label="Permalink to &quot;2. Session&quot;">​</a></h3><ul><li>存储在<strong>服务端</strong>，sessionId 存储在客户端 Cookie 中</li><li><strong>集群部署的 Session 共享问题</strong>：多台服务器间需共享 Session（可用 Redis）</li><li>关闭浏览器 Session 不会立即消失：只是会话 Cookie 丢失导致找不到 Session</li></ul><p><strong>分布式 Session 共享方案</strong>：</p><table tabindex="0"><thead><tr><th>方案</th><th>原理</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>Session 复制</td><td>节点 Session 变化时广播给所有节点</td><td>可容错</td><td>网络压力大</td></tr><tr><td>粘性 Session</td><td>Nginx ip_hash 定向到同一服务器</td><td>简单</td><td>服务器故障则 Session 失效</td></tr><tr><td>Session 共享（常用）</td><td>Redis/Memcached 集群缓存</td><td>可扩展，重启不丢失</td><td>架构复杂</td></tr><tr><td>Session 持久化</td><td>存储到数据库</td><td>故障不丢失</td><td>数据库压力大</td></tr></tbody></table><h3 id="_3-cookie-vs-session" tabindex="-1">3. Cookie vs Session <a class="header-anchor" href="#_3-cookie-vs-session" aria-label="Permalink to &quot;3. Cookie vs Session&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比项</th><th>Cookie</th><th>Session</th></tr></thead><tbody><tr><td>存储位置</td><td>客户端</td><td>服务端</td></tr><tr><td>安全性</td><td>较低（可被篡改）</td><td>较高</td></tr><tr><td>数据类型</td><td>仅字符串</td><td>任意类型</td></tr><tr><td>存储大小</td><td>≤ 4KB</td><td>远大于 Cookie</td></tr><tr><td>服务器压力</td><td>无</td><td>用户多时占用内存</td></tr></tbody></table><h3 id="_4-token" tabindex="-1">4. Token <a class="header-anchor" href="#_4-token" aria-label="Permalink to &quot;4. Token&quot;">​</a></h3><ul><li>访问资源接口（API）时所需的<strong>资源凭证</strong></li><li>简单组成：<code>uid</code>（用户唯一标识）+ <code>time</code>（时间戳）+ <code>sign</code>（签名/哈希）</li><li>token 放在 HTTP Header 的 <code>Authorization</code> 字段中</li><li><strong>服务端无状态</strong>：不存储 token，用解析计算时间换取存储空间</li><li>可避开同源策略，可避免 CSRF 攻击</li></ul><p><strong>Access Token vs Refresh Token</strong>：</p><ul><li>Access Token 有效期短（几分钟），用于访问资源</li><li>Refresh Token 有效期长，专用于刷新过期的 Access Token</li><li>流程：登录 → access+refresh token → access 过期 → 用 refresh 换新 access → refresh 也过期 → 重新登录</li></ul><h3 id="_5-jwt-json-web-token" tabindex="-1">5. JWT（JSON Web Token） <a class="header-anchor" href="#_5-jwt-json-web-token" aria-label="Permalink to &quot;5. JWT（JSON Web Token）&quot;">​</a></h3><p><strong>JWT 结构（三段式，<code>.</code> 分隔）</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Header.Payload.Signature</span></span>
<span class="line"><span>// 例：eyJhbGciOiJIUzI1NiJ9.eyJ1c2VySWQiOiJhIn0.2jf3kl_uKWRkwjOP6uQRJFqMw</span></span></code></pre></div><ul><li><strong>Header</strong>：算法类型（<code>alg: HS256</code>）+ 令牌类型（<code>typ: JWT</code>），base64url 编码</li><li><strong>Payload</strong>：实际数据（用户信息、<code>iat</code> 签发时间、<code>exp</code> 过期时间），base64url 编码</li><li><strong>Signature</strong>：<code>HMACSHA256(base64(Header) + &quot;.&quot; + base64(Payload), secret)</code>，防篡改</li></ul><p><strong>防篡改原理</strong>：用户可修改 base64 数据，但无法伪造签名（因不知道 secret）</p><p><strong>优势</strong>：无状态（可扩展）、自包含（减少数据库查询）、跨域友好（不依赖 Cookie）</p><p><strong>缺点</strong>：无法主动废弃；默认不加密；应设置较短有效期，通过 HTTPS 传输</p><h3 id="_6-单点登录-sso" tabindex="-1">6. 单点登录（SSO） <a class="header-anchor" href="#_6-单点登录-sso" aria-label="Permalink to &quot;6. 单点登录（SSO）&quot;">​</a></h3><p><strong>同主域名</strong>：将 Cookie 的 <code>domain</code> 设为主域名，所有子域共享登录状态</p><p><strong>跨主域名（真正 SSO）</strong>：</p><ol><li>用户访问系统 A → 未登录 → 跳转 SSO</li><li>SSO 验证账号密码 → 种 SSO 域下凭证 + 下发 <code>code</code>（一次性）</li><li>重定向回系统 A 的 callback，携带 <code>code</code></li><li>系统 A 用 <code>code</code> 向 SSO 换取 <code>ticket</code>，在 A 域下 set cookie</li><li>用户访问系统 B → 未登录 → 跳转 SSO → 已有凭证 → 下发 code → B 用 code 换 ticket</li></ol><p><strong>关键点</strong>：<code>code</code> 是一次性的，暴露在 URL 中仅用于换取 ticket，换完即失效</p><h3 id="_7-session-vs-token-对比" tabindex="-1">7. Session vs Token 对比 <a class="header-anchor" href="#_7-session-vs-token-对比" aria-label="Permalink to &quot;7. Session vs Token 对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比维度</th><th>Session</th><th>Token</th></tr></thead><tbody><tr><td>客户端存储</td><td>Cookie（自动携带）</td><td>灵活（Cookie/localStorage/Header）</td></tr><tr><td>服务端存储</td><td>存储完整会话数据</td><td>不存储，仅校验签名</td></tr><tr><td>CSRF 风险</td><td>有（Cookie 自动携带）</td><td>无（手动放入 Header）</td></tr><tr><td>跨端支持</td><td>仅浏览器（依赖 Cookie）</td><td>全平台（APP/小程序/IoT）</td></tr><tr><td>分布式</td><td>需共享存储（Redis）</td><td>天然支持（无状态）</td></tr></tbody></table><hr><h2 id="四、cdn-与-dns" tabindex="-1">四、CDN 与 DNS <a class="header-anchor" href="#四、cdn-与-dns" aria-label="Permalink to &quot;四、CDN 与 DNS&quot;">​</a></h2><h3 id="_1-cdn-内容分发网络" tabindex="-1">1. CDN（内容分发网络） <a class="header-anchor" href="#_1-cdn-内容分发网络" aria-label="Permalink to &quot;1. CDN（内容分发网络）&quot;">​</a></h3><ul><li><strong>原理</strong>：在用户附近部署缓存节点，就近响应用户请求</li><li><strong>优势</strong>：解决跨运营商/跨地域访问问题，降低延迟；分流减轻源站负载</li><li><strong>缓存策略</strong>：通过 <code>Cache-Control: max-age</code> 控制节点缓存时间，过期则回源拉取</li></ul><h3 id="_2-dns-解析过程" tabindex="-1">2. DNS 解析过程 <a class="header-anchor" href="#_2-dns-解析过程" aria-label="Permalink to &quot;2. DNS 解析过程&quot;">​</a></h3><ol><li>浏览器自身 DNS 缓存</li><li>操作系统 hosts 文件</li><li>本地 DNS 服务器（ISP）</li><li>根服务器递归查询</li></ol><hr><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./rendering.html">浏览器进程与渲染</a> — 多进程架构、渲染流程</li><li><a href="./security.html">安全</a> — XSS、CSRF 防御</li><li><a href="./../performance/">性能优化专题</a> — 网络层优化（gzip/CDN/缓存策略）</li></ul>`,75)])])}const p=e(r,[["render",i]]);export{S as __pageData,p as default};
